INSERT INTO public.stellar_natal_rewards_v132(id,definition)
SELECT 'design:'||(definition->>'design_id'),definition||jsonb_build_object('bonuses',d.bonuses,'eligibility',d.eligibility) FROM approved a JOIN public.live_designs_v16 d ON d.design_id=a.definition->>'design_id'
ON CONFLICT(id) DO UPDATE SET definition=excluded.definition;
NOTIFY pgrst,'reload schema';
COMMIT;
